/**
 * Thin client for the Slack provisioning API on the Cursor backend ("Add
 * to Slack"), on the architecture v2 control plane (`/internal/agentsdk/slack`).
 * The wizard session, its poll, the token storage, and the app inventory all
 * live there. Pure request/response + error mapping — no console I/O, no
 * polling loops; rendering lives in `cli-slack.ts`.
 *
 * Auth is the user API key sent directly as the bearer (the routes are
 * `wrapUserApiRoute` on the backend); there is no token exchange here.
 * The endpoints ride `requireAgentServeAccess` and 404 `{ error: "Not found" }`
 * when Agent Serve is off — same mapping as other agent-sdk deploy 404s.
 * Expected provisioning failures carry a stable JSON `code`
 * (`not_connected`, `insufficient_scopes`, `manager_reauth_required`,
 * `app_conflict`, `ratelimited`, `invalid_app_id`, …)
 * which flows through on {@link SlackProvisionApiError.code} so the CLI
 * can branch.
 */
import * as z from "zod/v4";
import { cliRequestHeaders } from "./cli-invocation.js";
import { stopIfDryRun } from "./dry-run.js";
import { isRecord } from "./is-record.js";
/**
 * Backend mount of the architecture v2 Slack control plane. Its routes
 * reject a wizard mint or token storage that does not name `"v2"`.
 */
const SLACK_CONTROL_PLANE_BASE_PATH = "/internal/agentsdk/slack";
export class SlackProvisionApiError extends Error {
    constructor(message, options) {
        super(message);
        this.name = "SlackProvisionApiError";
        this.status = options.status;
        this.code = options.code;
        this.retryAfterSeconds = options.retryAfterSeconds;
        this.changedPaths = options.changedPaths;
    }
}
// ============================================================================
// Response shapes (backend agentServeSlackEndpoints route bodies).
// Interfaces are hand-written (the package compiles with
// --isolatedDeclarations, so exported types cannot be z.infer of an
// unannotated schema); the zod schemas below stay module-internal.
// ============================================================================
// All response schemas are `.passthrough()` so unknown fields from a newer
// backend flow through untouched instead of breaking the parse.
const statusResponseSchema = z
    .object({
    workspaces: z.array(z
        .object({
        slackTeamId: z.string(),
        slackTeamName: z.string().nullish(),
        slackUserId: z.string(),
        connectedAt: z.string(),
    })
        .passthrough()),
    apps: z.array(z
        .object({
        slackAppId: z.string(),
        slackTeamId: z.string(),
        slug: z.string(),
        env: z.string(),
        installStatus: z.string(),
        createdAt: z.string(),
        updatedAt: z.string(),
    })
        .passthrough()),
})
    .passthrough();
const connectResponseSchema = z
    .object({
    url: z.string().min(1),
})
    .passthrough();
const provisionResponseSchema = z.discriminatedUnion("status", [
    z
        .object({
        status: z.literal("installed"),
        appId: z.string(),
        botToken: z.string(),
        appToken: z.string().optional(),
        iconStatus: z.enum(["set", "failed"]).optional(),
    })
        .passthrough(),
    z
        .object({
        status: z.literal("pending_admin_approval"),
        appId: z.string(),
        oauthAuthorizeUrl: z.string().optional(),
        iconStatus: z.enum(["set", "failed"]).optional(),
    })
        .passthrough(),
]);
const deleteResponseSchema = z
    .object({
    deleted: z.boolean(),
})
    .passthrough();
const setIconResponseSchema = z
    .object({
    ok: z.boolean(),
})
    .passthrough();
const mintWizardResponseSchema = z
    .object({
    wizardId: z.string().min(1),
    url: z.string().min(1),
})
    .passthrough();
const wizardPollResponseSchema = z
    .object({
    wizardId: z.string(),
    teamId: z.number(),
    slug: z.string(),
    env: z.string(),
    status: z.string(),
    appId: z.string().optional(),
    oauthAuthorizeUrl: z.string().optional(),
    approvalRequest: z.string().optional(),
    error: z.string().optional(),
    localEnv: z
        .object({
        botToken: z.string().min(1),
        appToken: z.string().optional(),
    })
        .optional(),
    localEnvClaimed: z.boolean().optional(),
})
    .passthrough();
export class AgentServeSlackClient {
    constructor(options) {
        this.basePath = SLACK_CONTROL_PLANE_BASE_PATH;
        this.backendUrl = options.backendUrl.endsWith("/")
            ? options.backendUrl.slice(0, -1)
            : options.backendUrl;
        this.apiKey = options.apiKey;
        this.fetchImpl = options.fetchImpl ?? fetch;
    }
    /** Manager-connected workspaces + the managed-app inventory. */
    async status(teamId) {
        const raw = await this.request({
            method: "GET",
            path: `${this.basePath}/status?teamId=${teamId}`,
            context: { verb: "read Slack provisioning status" },
        });
        return statusResponseSchema.parse(raw);
    }
    /**
     * Mint the browser consent URL for the Slack manager grant. After the
     * user approves it, the workspace shows up in {@link status}.
     */
    async connect(teamId) {
        const raw = await this.request({
            method: "POST",
            path: `${this.basePath}/connect`,
            body: { teamId },
            context: { verb: "start the Slack workspace connect" },
        });
        return connectResponseSchema.parse(raw).url;
    }
    /**
     * Open a dashboard wizard session on the v2 control plane. The session
     * records the architecture, so the dashboard stores the minted tokens on
     * the v2 deployment and the poll below can find it.
     */
    async mintWizard(input) {
        const raw = await this.request({
            method: "POST",
            path: `${this.basePath}/wizard`,
            body: { ...input, architecture: "v2" },
            context: { verb: "start Slack setup" },
        });
        return mintWizardResponseSchema.parse(raw);
    }
    async pollWizard(wizardId) {
        const raw = await this.request({
            method: "GET",
            path: `${this.basePath}/wizard/${encodeURIComponent(wizardId)}`,
            context: { verb: "poll Slack setup" },
        });
        return wizardPollResponseSchema.parse(raw);
    }
    /**
     * Provision (create or update) and install one managed Slack app for
     * (slackTeamId, slug, env). Expected failures throw
     * {@link SlackProvisionApiError} with a stable `code`.
     */
    async provisionApp(args) {
        const raw = await this.request({
            method: "POST",
            path: `${this.basePath}/apps`,
            body: {
                teamId: args.teamId,
                slackTeamId: args.slackTeamId,
                slug: args.slug,
                env: args.env,
                manifest: args.manifest,
                icon: args.icon,
                force: args.force,
            },
            context: { verb: "provision the Slack app" },
        });
        return provisionResponseSchema.parse(raw);
    }
    /** Delete the Slack app and its inventory row. */
    async deleteApp(args) {
        const raw = await this.request({
            method: "DELETE",
            path: `${this.basePath}/apps/${encodeURIComponent(args.slackAppId)}?teamId=${args.teamId}`,
            context: { verb: "delete the Slack app" },
        });
        deleteResponseSchema.parse(raw);
    }
    /** Set the app's icon: an https image URL or a base64 png/jpeg/gif ≤512KB. */
    async setAppIcon(args) {
        const raw = await this.request({
            method: "POST",
            path: `${this.basePath}/apps/${encodeURIComponent(args.slackAppId)}/icon`,
            body: { teamId: args.teamId, icon: args.icon },
            context: { verb: "set the Slack app icon" },
        });
        setIconResponseSchema.parse(raw);
    }
    async request(args) {
        stopIfDryRun({ method: args.method, path: args.path, body: args.body });
        const headers = {
            ...cliRequestHeaders(),
            accept: "application/json",
            authorization: `Bearer ${this.apiKey}`,
        };
        if (args.body !== undefined) {
            headers["content-type"] = "application/json";
        }
        let response;
        try {
            response = await this.fetchImpl(`${this.backendUrl}${args.path}`, {
                method: args.method,
                headers,
                body: args.body === undefined ? undefined : JSON.stringify(args.body),
                signal: AbortSignal.timeout(60_000),
            });
        }
        catch (error) {
            throw new SlackProvisionApiError(`Could not reach the Cursor backend at ${this.backendUrl}: ${error instanceof Error ? error.message : String(error)}`, { status: 0 });
        }
        const text = await response.text();
        if (!response.ok) {
            throw mapErrorResponse(response, text, args.context);
        }
        try {
            return JSON.parse(text);
        }
        catch {
            throw new SlackProvisionApiError(`The Cursor backend returned a non-JSON response to ${args.context.verb}.`, { status: response.status });
        }
    }
}
// ============================================================================
// Error mapping (HTTP → actionable human messages, stable codes kept)
// ============================================================================
function parseErrorBody(bodyText) {
    let parsed;
    try {
        parsed = JSON.parse(bodyText);
    }
    catch {
        return {};
    }
    if (!isRecord(parsed)) {
        return {};
    }
    return {
        error: typeof parsed.error === "string" && parsed.error !== "" ? parsed.error : undefined,
        code: typeof parsed.code === "string" && parsed.code !== "" ? parsed.code : undefined,
        retryAfterSeconds: typeof parsed.retryAfterSeconds === "number" ? parsed.retryAfterSeconds : undefined,
        changedPaths: Array.isArray(parsed.changedPaths) &&
            parsed.changedPaths.every((path) => typeof path === "string")
            ? parsed.changedPaths
            : undefined,
    };
}
function mapErrorResponse(response, bodyText, context) {
    const body = parseErrorBody(bodyText);
    const serverError = body.error;
    switch (response.status) {
        case 401:
            return new SlackProvisionApiError("The Cursor API key was rejected. Run `agent-sdk login` again or update CURSOR_API_KEY.", { status: 401 });
        case 403:
            return new SlackProvisionApiError(serverError ?? "Not authorized for this team", {
                status: 403,
            });
        case 404: {
            // Fastify's route-not-found envelope means we hit the wrong host
            // (api2 vs api.cursor.com), not a closed gate.
            if (/Route \S+ not found/i.test(bodyText)) {
                return new SlackProvisionApiError(`Agent Serve Slack API not found on this host — use the default api.cursor.com (unset CURSOR_API_BASE_URL), or point CURSOR_API_BASE_URL at a backend that mounts /internal/agent-serve/* and /internal/agentsdk/*.`, { status: 404 });
            }
            // `{ error: "Not found" }` is Agent Serve off (`requireAgentServeAccess`),
            // not a Slack-only enrollment bar.
            if (serverError !== undefined && serverError !== "Not found") {
                return new SlackProvisionApiError(serverError, {
                    status: 404,
                    code: body.code,
                });
            }
            return new SlackProvisionApiError(`Not found — check --team.`, { status: 404 });
        }
        case 429: {
            const retryAfterHeader = response.headers.get("retry-after");
            const retryAfterSeconds = retryAfterHeader !== null && /^\d+$/.test(retryAfterHeader)
                ? Number(retryAfterHeader)
                : body.retryAfterSeconds;
            return new SlackProvisionApiError(`${serverError ?? "Rate limited"}${retryAfterSeconds === undefined ? "" : ` — retry in ${retryAfterSeconds}s`}`, { status: 429, code: body.code ?? "ratelimited", retryAfterSeconds });
        }
        default:
            return new SlackProvisionApiError(serverError ??
                `The ${context.verb} request failed (${response.status}): ${bodyText.slice(0, 300) || "(empty body)"}`, {
                status: response.status,
                code: body.code,
                changedPaths: body.changedPaths,
            });
    }
}
